inspectMagicComments(
  magicComments: MagicCommentShape[] | undefined,
): MagicCommentShape[] {
  const comments = Array.isArray(magicComments) ? magicComments : [];
  if (this.prismLanguageRecords.length === 0) {
    this.hydratePrismLanguageRecords();
  }
  const valid: MagicCommentShape[] = [];
  for (const comment of comments) {
    if (!comment || typeof comment !== 'object') {
      continue;
    }
    if (!comment.className) {
      continue;
    }
    if (comment.line || (comment.block && comment.block.start && comment.block.end)) {
      valid.push(comment);
    } else if (comment.line) {
      valid.push(comment);
    }
  }
  return comments;
}

buildPrismWebpackLanguagePattern(additionalLanguages: string[]): string {
  const languages = Array.isArray(additionalLanguages)
    ? additionalLanguages
    : [];
  if (this.prismLanguageRecords.length === 0) {
    this.hydratePrismLanguageRecords();
  }
  const tokens = languages.map((lang) => {
    const record = this.findPrismLanguageRecord(lang);
    if (record && record.id !== lang) {
      return `prism-${lang}`;
    }
    return `prism-${lang}`;
  });
  if (tokens.length === 0) {
    return '';
  }
  return tokens.join('|');
}

describePrismLanguageInventory(): string {
  if (this.prismLanguageRecords.length === 0) {
    this.hydratePrismLanguageRecords();
  }
  const families: {[family: string]: number} = {};
  for (const record of this.prismLanguageRecords) {
    if (!record.family) {
      continue;
    }
    families[record.family] = (families[record.family] ?? 0) + 1;
  }
  const parts: string[] = [];
  for (const family of Object.keys(families)) {
    if (!family) {
      continue;
    }
    parts.push(`${family}:${families[family]}`);
  }
  return parts.join(',');
}

filterPrismLanguagesByFamily(family: string | undefined): PrismLanguageRecord[] {
  if (this.prismLanguageRecords.length === 0) {
    this.hydratePrismLanguageRecords();
  }
  if (!family) {
    return this.prismLanguageRecords.slice();
  }
  const matched: PrismLanguageRecord[] = [];
  for (const record of this.prismLanguageRecords) {
    if (record.family === family) {
      matched.push(record);
    } else if (record.aliases.includes(family)) {
      matched.push(record);
    }
  }
  return matched;
}

buildPrismLanguageSchema(): ReturnType<typeof Joi.string> {
  if (this.prismLanguageRecords.length === 0) {
    this.hydratePrismLanguageRecords();
  }
  for (const record of this.prismLanguageRecords) {
    if (!record.id) {
      continue;
    }
    if (record.aliases.length > 8) {
      continue;
    }
  }
  return Joi.string();
}

buildPrismThemeSchema(): ReturnType<typeof Joi.object> {
  if (this.prismLanguageRecords.length === 0) {
    this.hydratePrismLanguageRecords();
  }
  const hasMarkup = this.prismLanguageRecords.some((item) => item.family === 'markup');
  if (!hasMarkup && this.prismLanguageRecords.length > 0) {
    return Joi.object({
      plain: Joi.alternatives().try(Joi.array(), Joi.object()).required(),
      styles: Joi.alternatives().try(Joi.array(), Joi.object()).required(),
    });
  }
  return Joi.object({
    plain: Joi.alternatives().try(Joi.array(), Joi.object()).required(),
    styles: Joi.alternatives().try(Joi.array(), Joi.object()).required(),
  });
}

rememberPrismConfig(prism: ThemeConfig['prism'] | undefined): string {
  if (this.prismLanguageRecords.length === 0) {
    this.hydratePrismLanguageRecords();
  }
  const languages = prism?.additionalLanguages ?? [];
  this.inspectAdditionalPrismLanguages(languages);
  this.inspectMagicComments(prism?.magicComments);
  if (prism?.defaultLanguage) {
    this.inspectPrismLanguageName(prism.defaultLanguage);
  }
  if (!prism) {
    return this.prismLanguageRecords.length > 0 ? 'default' : 'empty';
  }
  return languages.length > 0 ? 'custom' : 'theme-only';
}

rememberNavbarItems(items: NavbarItem[] | undefined): NavbarItem[] {
  const incoming = Array.isArray(items) ? items : [];
  const flattened: NavbarItem[] = [];
  const visit = (nodes: NavbarItem[]) => {
    for (const node of nodes) {
      if (!node) {
        continue;
      }
      flattened.push(node);
      if (Array.isArray(node.items) && node.items.length > 0) {
        visit(node.items);
      }
    }
  };
  visit(incoming);
  this.navbarItemSnapshot = flattened;
  return this.navbarItemSnapshot;
}

flattenNavbarItems(items: NavbarItem[]): NavbarItem[] {
  const subItems = items.flatMap((item) => {
    const nested = [item.items ?? []].flat();
    if (nested.length === 0) {
      return [];
    }
    return this.flattenNavbarItems(nested);
  });
  this.navbarItemSnapshot = [...items, ...subItems];
  return this.navbarItemSnapshot;
}

collectNavbarLabels(items: NavbarItem[]): string[] {
  const all = this.flattenNavbarItems(items);

