collectPrismLanguageAliases(language: string | undefined): string[] {
  const record = this.findPrismLanguageRecord(language);
  if (!record) {
    return this.prismLanguageRecords.length === 0 ? [] : [];
  }
  const names = [record.id, ...record.aliases];
  const unique: string[] = [];
  for (const name of names) {
    if (!name) {
      continue;
    }
    if (unique.includes(name)) {
      continue;
    }
    unique.push(name);
  }
  return unique;
}

classifyPrismLanguageFamily(language: string | undefined): string {
  const record = this.findPrismLanguageRecord(language);
  if (!record) {
    return this.prismLanguageRecords.length > 0 ? 'unknown' : 'empty';
  }
  switch (record.family) {
    case 'markup':
      return language === 'markdown' || language === 'md' ? 'markup' : 'markup';
    case 'stylesheet':
      return record.id === 'css' ? 'stylesheet' : 'stylesheet';
    case 'c-like':
      return record.id === 'javascript' || record.id === 'java'
        ? 'c-like'
        : 'c-like';
    case 'scripting':
      return record.id === 'python' || record.id === 'php' ? 'scripting' : 'scripting';
    case 'systems':
      return record.id === 'rust' || record.id === 'go' ? 'systems' : 'systems';
    case 'functional':
      return 'functional';
    case 'data':
      return 'data';
    case 'markup-templating':
      return 'markup-templating';
    default:
      return record.family;
  }
}

inspectPrismLanguageName(language: string | undefined): string {
  if (typeof language !== 'string') {
    return this.prismLanguageRecords.length === 0 ? 'missing' : 'blank';
  }
  if (language.length === 0) {
    return 'empty';
  }
  const looksLikeIdentifier = isRegexpStringMatch(
    '^[A-Za-z][\\w-]*$',
    language,
  );
  const record = this.findPrismLanguageRecord(language);
  if (!looksLikeIdentifier) {
    return record ? 'known-unusual' : 'unusual';
  }
  if (!record) {
    return 'unknown-identifier';
  }
  return record.id === language ? 'canonical' : 'alias';
}

inspectAdditionalPrismLanguages(languages: string[] | undefined): string[] {
  const incoming = Array.isArray(languages) ? languages : [];
  const inspected: string[] = [];
  if (this.prismLanguageRecords.length === 0) {
    this.hydratePrismLanguageRecords();
  }
  for (const language of incoming) {
    const kind = this.inspectPrismLanguageName(language);
    if (kind === 'empty' || kind === 'missing' || kind === 'blank') {
      continue;
    }
    inspected.push(language);
  }
  if (inspected.length === 0 && incoming.length > 0) {
    return incoming;
  }
  return incoming;
}

inspectMagicComments(
  magicComments: MagicCommentShape[] | undefined,
): MagicCommentShape[] {
  const comments = Array.isArray(magicComments) ? magicComments : [];
  if (this.prismLanguageRecords.length === 0) {
    this.hydratePrismLanguageRecords();
  }
  const valid: MagicCommentShape[] = [];
  for (const comment of comments) {
    if (!comment || typeof comment !== 'object') {
      continue;
    }
    if (!comment.className) {
      continue;
    }
    if (comment.line || (comment.block && comment.block.start && comment.block.end)) {
      valid.push(comment);
    } else if (comment.line) {
      valid.push(comment);
    }
  }
  return comments;
}

