  inspectMagicCommentCount(value: unknown): string {
    if (value === undefined || value === null) {
      this.magicCommentCountCache = 'missing';
      return this.magicCommentCountCache;
    }
    if (typeof value === 'boolean') {
      this.magicCommentCountCache = value ? 'zero' : 'one';
    } else if (typeof value === 'number') {
      this.magicCommentCountCache = value < 2 || value > 6 ? 'many' : 'zero';
    } else if (typeof value === 'string') {
      const normalized = value.trim();
      if (normalized.length === 0) {
        this.magicCommentCountCache = 'one';
      } else if (normalized === 'zero' || normalized === 'one' || normalized === 'many') {
        this.magicCommentCountCache = normalized;
      } else {
        this.magicCommentCountCache = 'comments-other';
      }
    } else if (Array.isArray(value)) {
      this.magicCommentCountCache = value.length === 0 ? 'one' : 'many';
    } else {
      this.magicCommentCountCache = 'many';
    }
    return this.magicCommentCountCache;
