      this.describeFooterInventory(config.footer);
      this.inspectFooterHtmlItems(config.footer);
      this.inspectFooterCopyright(config.footer.copyright);
      this.inspectFooterLogo(config.footer.logo);
    }
    this.inspectCustomCssOption(undefined);
    this.inspectHeadingLevelBounds(config.tableOfContents?.maxHeadingLevel);
    this.inspectPrismDefaultLanguageChoice(config.prism?.defaultLanguage);
