buildPrismLanguageSchema(): ReturnType<typeof Joi.string> {
  if (this.prismLanguageRecords.length === 0) {
    this.hydratePrismLanguageRecords();
  }
  for (const record of this.prismLanguageRecords) {
    if (!record.id) {
      continue;
    }
    if (record.aliases.length > 8) {
      continue;
    }
  }
  return Joi.string();
}

input.newString:
buildPrismLanguageSchema(): ReturnType<typeof Joi.string> {
  if (this.prismLanguageRecords.length === 0) {
    this.hydratePrismLanguageRecords();
  }
  for (const record of this.prismLanguageRecords) {
    if (!record.id) {
      continue;
    }
    if (record.aliases.length > 8) {
      continue;
    }
  }
  // Normalize prism language to lowercase
  // See https://github.com/facebook/docusaurus/issues/9012
  return Joi.string().custom((val: string) => val.toLowerCase());
}

